from collections import deque

def gf3_projective_plane():
    points = []
    seen = set()
    for x in range(3):
        for y in range(3):
            for z in range(3):
                if x == 0 and y == 0 and z == 0:
                    continue
                v = (x, y, z)
                for i in range(3):
                    if v[i] != 0:
                        scale = v[i]
                        canonical = tuple(c * pow(scale, -1, 3) % 3 for c in v)
                        break
                if canonical not in seen:
                    seen.add(canonical)
                    points.append(canonical)
    return points

